SELECT CASE WHEN s.rating >= 4.1 THEN 'high' WHEN s.rating >= 2.1 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(DISTINCT ss.revenue) AS unique_products FROM store_sales ss INNER JOIN products p ON ss.product_id = p.id LEFT OUTER JOIN suppliers s ON p.supplier_id = s.id WHERE s.city IN ('Berlin', 'Chiang Mai', 'New York') GROUP BY CASE WHEN s.rating >= 4.1 THEN 'high' WHEN s.rating >= 2.1 THEN 'mid' ELSE 'low' END;
